import{_ as a,a as r}from"./chunks/rt_dt.DBwJICWL.js";import{_ as e,o as l,c as d,a0 as o}from"./chunks/framework.akKRIpjQ.js";const q=JSON.parse('{"title":"05 · 张力换算","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/05-tension-conversion.md","filePath":"zh/guide/05-tension-conversion.md"}'),i={name:"zh/guide/05-tension-conversion.md"};function s(n,t,h,b,u,c){return l(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="_05-·-张力换算" tabindex="-1">05 · 张力换算 <a class="header-anchor" href="#_05-·-张力换算" aria-label="Permalink to &quot;05 · 张力换算&quot;">​</a></h1><blockquote><p>4 个功能中的第 4 个。<strong>DT ⇄ RT</strong>（动态张力 / 参考张力）以及 <strong>lbs ⇄ kg</strong>（拉力量纲）互转。结果页底部 **「用此张力记录穿线」**一键跳到 <a href="./04-stringing-log.html">04 · 穿线记录</a>，磅数预填。</p></blockquote><h2 id="它能做什么" tabindex="-1">它能做什么 <a class="header-anchor" href="#它能做什么" aria-label="Permalink to &quot;它能做什么&quot;">​</a></h2><p>首页两张大卡片里有一张叫「张力换算」；「球拍」Tab 也能进。一卡内三种换算模式（toggle 切换）：</p><ul><li><strong>DT → RT</strong> —— 输入穿线机报的 DT（动态张力）→ 得到 RT（参考张力 / 静态张力），lbs &amp; kg 同步显示</li><li><strong>RT → DT</strong> —— 输入 RT 的 lbs 数 → 反查 DT 值</li><li><strong>lbs ⇄ kg</strong> —— 拉力量纲互转</li></ul><p>每个结果页都包含：</p><ul><li>换算后的值</li><li>置信度提示（「误差 ±1 lbs 以内」）</li><li>**「用此张力记录穿线」**按钮 —— 直接跳到 <a href="./04-stringing-log.html">04 · 穿线记录 → 添加穿线记录</a>，磅数预填</li></ul><h2 id="拍面档位-dt-⇄-rt-用" tabindex="-1">拍面档位（DT ⇄ RT 用） <a class="header-anchor" href="#拍面档位-dt-⇄-rt-用" aria-label="Permalink to &quot;拍面档位（DT ⇄ RT 用）&quot;">​</a></h2><p>App 的 DT ⇄ RT 换算按 <strong>3 档拍面</strong>来查（与 ERT300 穿线机的 DT 锚点表一致）。选一个最贴近你球拍的档就行，不用记精确拍面数字。</p><table tabindex="0"><thead><tr><th>档位</th><th>平方英寸</th><th>cm²</th><th>常见球拍类型</th></tr></thead><tbody><tr><td><strong>MID</strong></td><td>83–94</td><td>540–610</td><td>控球型 / 小拍面（职业款）</td></tr><tr><td><strong>MID+</strong></td><td>95–105</td><td>611–680</td><td>多数现代球拍（默认）</td></tr><tr><td><strong>OVER</strong></td><td>106–115</td><td>681–740</td><td>大拍面 / 休闲款</td></tr></tbody></table><blockquote><p>picker 里档位 label 跟随你的<strong>面积单位设置</strong> —— 英制用户看平方英寸，公制用户看 cm²。在 <a href="./06-settings-faq.html">设置 → 面积单位</a> 切换。cm² ↔ 平方英寸<strong>不自动联动</strong>（档位边界非整数对齐）。</p></blockquote><p>DT ⇄ RT 的算式用的是「线材 × 档位」查找表，数据来自 USRSA 公开 bulletin；档位选择是 App 唯一要的拍面输入。</p><h2 id="dt-→-rt-主打功能" tabindex="-1">DT → RT（主打功能） <a class="header-anchor" href="#dt-→-rt-主打功能" aria-label="Permalink to &quot;DT → RT（主打功能）&quot;">​</a></h2><img src="'+a+'" alt="DT 转 RT" style="max-width:320px;border-radius:12px;margin:12px 0;"><p>穿线机一般报 DT 或 RT 中的一个。在 App 里切换单位就能得到另一套数值。</p><h3 id="输入" tabindex="-1">输入 <a class="header-anchor" href="#输入" aria-label="Permalink to &quot;输入&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td>原始磅数</td><td>空</td><td>数字 + 单位（lbs 或 kg）</td></tr><tr><td>方向</td><td>DT → RT（默认）</td><td>或 RT → DT</td></tr><tr><td>线材类型</td><td>聚酯（默认）</td><td>聚酯 / 多股尼龙 / 肠线 —— 不同线材换算系数不同</td></tr><tr><td>拍面档位</td><td>MID+（默认）</td><td>三档 —— 见 <a href="#拍面档位dt--rt-用">拍面档位</a></td></tr></tbody></table><h3 id="输出示例" tabindex="-1">输出示例 <a class="header-anchor" href="#输出示例" aria-label="Permalink to &quot;输出示例&quot;">​</a></h3><table tabindex="0"><thead><tr><th>输入</th><th>输出</th></tr></thead><tbody><tr><td>DT 60 lbs · 聚酯 · MID+</td><td>RT 56.4 lbs</td></tr><tr><td>RT 56 lbs · 多股尼龙 · MID+</td><td>DT 58.7 lbs</td></tr></tbody></table><blockquote><p>换算使用一张&quot;线材 × 档位&quot;查找表，系数来自 USRSA 公开 bulletin。</p></blockquote><h3 id="什么时候不该信这次的换算" tabindex="-1">什么时候<strong>不该</strong>信这次的换算? <a class="header-anchor" href="#什么时候不该信这次的换算" aria-label="Permalink to &quot;什么时候**不该**信这次的换算?&quot;">​</a></h3><ul><li><strong>线材类型不明</strong> —— 不确定是聚酯 / 多股尼龙 / 肠线，结果可能偏 ±2 lbs</li><li><strong>球拍正好压在档位边界</strong> —— 例 95 in² 的拍子正好踩在 MID / MID+ 之间，按厂家规格书选更稳的一档</li><li><strong>混合线材</strong>（main 和 cross 不同线）—— 两侧要分别算；App 也按两条记录来处理</li></ul><h2 id="dt-⇄-rt-换算速查表" tabindex="-1">DT ⇄ RT 换算速查表 <a class="header-anchor" href="#dt-⇄-rt-换算速查表" aria-label="Permalink to &quot;DT ⇄ RT 换算速查表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>档位</th><th>聚酯</th><th>多股尼龙</th><th>肠线</th></tr></thead><tbody><tr><td>MID（83–94 in²）</td><td>0.94</td><td>0.97</td><td>0.99</td></tr><tr><td>MID+（95–105 in²）</td><td>0.93</td><td>0.96</td><td>0.98</td></tr><tr><td>OVER（106–115 in²）</td><td>0.91</td><td>0.94</td><td>0.96</td></tr></tbody></table><blockquote><p>系数 = <code>RT / DT</code>。DT → RT 乘以系数；RT → DT 除以系数。</p></blockquote><h2 id="rt-⇄-dt-反方向" tabindex="-1">RT ⇄ DT（反方向） <a class="header-anchor" href="#rt-⇄-dt-反方向" aria-label="Permalink to &quot;RT ⇄ DT（反方向）&quot;">​</a></h2><img src="'+r+`" alt="RT 转 DT" style="max-width:320px;border-radius:12px;margin:12px 0;"><p>与上图相反：穿线机给 RT，你想换算成 DT（或反之）。输入相同，方向相反。</p><h2 id="lbs-⇄-kg" tabindex="-1">lbs ⇄ kg <a class="header-anchor" href="#lbs-⇄-kg" aria-label="Permalink to &quot;lbs ⇄ kg&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kg = lbs × 0.4536</span></span>
<span class="line"><span>lbs = kg × 2.2046</span></span></code></pre></div><table tabindex="0"><thead><tr><th>拉力 (lbs / kg)</th><th>风格</th></tr></thead><tbody><tr><td>40 / 18.1</td><td>极松（休闲）</td></tr><tr><td>50 / 22.7</td><td>松</td></tr><tr><td>55 / 24.9</td><td>标准男</td></tr><tr><td>60 / 27.2</td><td>标准男偏紧</td></tr><tr><td>65 / 29.5</td><td>紧</td></tr><tr><td>70 / 31.8</td><td>极紧（专业）</td></tr></tbody></table><blockquote><p>这里的 &quot;lbs&quot; 是 <strong>磅力</strong>（lbf），不是英制质量磅。日常直接说&quot;50 磅&quot;就行。</p></blockquote><p>lbs ⇄ kg 与 DT ⇄ RT 在同一页：切换顶部 tab 即可。</p><hr><h2 id="⤳-用此张力记录穿线" tabindex="-1">⤳ 用此张力记录穿线 <a class="header-anchor" href="#⤳-用此张力记录穿线" aria-label="Permalink to &quot;⤳ 用此张力记录穿线&quot;">​</a></h2><p>任何一个换算结果页的最下方，都有一个大按钮：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ 用此张力记录穿线 ]</span></span></code></pre></div><h3 id="它做了什么" tabindex="-1">它做了什么 <a class="header-anchor" href="#它做了什么" aria-label="Permalink to &quot;它做了什么&quot;">​</a></h3><ul><li>默认选当前球拍（无上下文时让你从列表选一支）</li><li>预填 <a href="./04-stringing-log.html">04 · 穿线记录 → 添加穿线记录</a> 表单： <ul><li>日期 = 今天</li><li>主磅 = 换算后的（统一到 lbs）</li><li>横磅 = 沿用球拍档案</li><li>来源 = <code>来自张力换算</code></li></ul></li><li>记录的 <strong>来源</strong> 字段会保留，未来可追溯&quot;这条数据是哪里来的&quot;</li></ul><h3 id="什么时候用" tabindex="-1">什么时候用 <a class="header-anchor" href="#什么时候用" aria-label="Permalink to &quot;什么时候用&quot;">​</a></h3><ul><li>你刚拿到穿线机拍的穿线工单，机器显示 DT 60 lbs</li><li>你想在 App 记录这次穿线、触发换线提醒</li><li>直接按这个键，免得再敲一遍数字</li></ul><h3 id="什么时候不要用" tabindex="-1">什么时候<strong>不要</strong>用 <a class="header-anchor" href="#什么时候不要用" aria-label="Permalink to &quot;什么时候**不要**用&quot;">​</a></h3><ul><li>你只是在&quot;如果 RT 56 lbs 等于 DT 多少&quot;做心算，没有记录意图</li><li>给老穿线补录（来源 tag 会留着，但日期记得改成真实那天）</li></ul><h3 id="保存前可编辑" tabindex="-1">保存前可编辑 <a class="header-anchor" href="#保存前可编辑" aria-label="Permalink to &quot;保存前可编辑&quot;">​</a></h3><p>预填的字段全部可改；点 <code>保存</code> 前随便调。来源 tag 永远是 <code>来自张力换算</code>，与是否修改无关。</p><h2 id="局限性" tabindex="-1">局限性 <a class="header-anchor" href="#局限性" aria-label="Permalink to &quot;局限性&quot;">​</a></h2><ul><li>❌ <strong>不考虑穿线机误差</strong>：每台机器都 ±2 lbs 的固有漂移</li><li>❌ <strong>不考虑温湿度</strong>：35 °C 下打了几个小时后，床面磅数会掉 ~2 lbs</li><li>❌ <strong>线材类型置信度</strong>：&quot;我也不清楚穿了啥&quot; → 结果落在宽区间；保存后补充实际线材</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="不走这里能直接录穿线吗" tabindex="-1">不走这里能直接录穿线吗? <a class="header-anchor" href="#不走这里能直接录穿线吗" aria-label="Permalink to &quot;不走这里能直接录穿线吗?&quot;">​</a></h3><p>可以。「穿线记录」是独立功能，跳转只是个快捷方式。</p><h3 id="lbs-⇄-kg-与-dt-⇄-rt-的系数会更新吗" tabindex="-1">lbs ⇄ kg 与 DT ⇄ RT 的系数会更新吗? <a class="header-anchor" href="#lbs-⇄-kg-与-dt-⇄-rt-的系数会更新吗" aria-label="Permalink to &quot;lbs ⇄ kg 与 DT ⇄ RT 的系数会更新吗?&quot;">​</a></h3><p>系数表打包进 App，跟随 App 版本走；运行时不联网取新系数 —— 这点保证了可复现。</p><h3 id="我换算的是-老穿线-怎么办" tabindex="-1">我换算的是&quot;老穿线&quot;怎么办? <a class="header-anchor" href="#我换算的是-老穿线-怎么办" aria-label="Permalink to &quot;我换算的是&quot;老穿线&quot;怎么办?&quot;">​</a></h3><p>点 <strong>用此张力记录穿线</strong>，到表单里把日期改成真实那天，保存。来源 tag 还是「来自张力换算」，但日期以你填的为准。</p><h2 id="数据来源" tabindex="-1">数据来源 <a class="header-anchor" href="#数据来源" aria-label="Permalink to &quot;数据来源&quot;">​</a></h2><p>DT ⇄ RT 系数用&quot;线材 × 档位&quot;查找表，来自 USRSA 公开 bulletin 和各穿线机厂商资料。每条都有源；运行时不联网取新系数。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="./04-stringing-log.html">04 · 穿线记录</a> —— 跳转后落点</li><li><a href="./03-racquets.html">03 · 球拍档案</a> —— 跳转依赖的球拍</li></ul>`,58)])])}const T=e(i,[["render",s]]);export{q as __pageData,T as default};
